"""DoubleTake: the install's steps scrolling past in a terminal-style panel.

The installer imports every file in this folder when it starts, looking for its screens.
This one has no screen of its own (__all__ is empty); importing it attaches to the
installer's own progress screen: the progress bar and its one-line label give way to a
dark panel that prints each step as it happens, with the time, and below it a thin line
across the panel's width that fills left to right with the install's overall progress,
orange blending to green like the DoubleTake ring.

Everything here is guarded. If the installer is a version this does not fit (a newer
Rocky), nothing changes and the installer shows its own progress bar, as it always has.
"""

import logging
import time

__all__ = []  # no screens here: the installer's collector picks up nothing from this file

log = logging.getLogger("anaconda.doubletake")

MAX_LINES = 500
LINE_HEIGHT = 6  # the progress line, in pixels
ORANGE = (1.0, 0.416, 0.075)  # #ff6a13, as the ring
GREEN = (0.243, 0.812, 0.557)  # #3ecf8e
TROUGH = (0.173, 0.188, 0.212)  # #2c3036, as the panel's border


def _draw_line(cr, width, height, fraction):
    """The progress line: the empty part dark, the done part a gradient that runs across the
    whole width (so the colour at a point is the same however far along the install is)."""
    import cairo

    radius = height / 2.0

    def rounded(w):
        cr.new_sub_path()
        cr.arc(w - radius, radius, radius, -1.5708, 1.5708)
        cr.arc(radius, radius, radius, 1.5708, 4.7124)
        cr.close_path()

    cr.set_source_rgb(*TROUGH)
    rounded(width)
    cr.fill()
    done = max(0.0, min(1.0, fraction)) * width
    if done >= height:  # at least a round dot, else nothing yet
        gradient = cairo.LinearGradient(0, 0, width, 0)
        gradient.add_color_stop_rgb(0.0, *ORANGE)
        gradient.add_color_stop_rgb(1.0, *GREEN)
        cr.set_source(gradient)
        rounded(done)
        cr.fill()
CSS = b"""
.doubletake-terminal, .doubletake-terminal text {
    background-color: #16181b;
    color: #d7dbe0;
    font-family: "DejaVu Sans Mono", monospace;
    font-size: 13pt;
}
.doubletake-terminal { padding: 14px 16px; }
.doubletake-frame { border: 1px solid #2c3036; border-radius: 6px; background-color: #16181b; }
"""


def _add_panel(spoke):
    import gi

    gi.require_version("Gtk", "3.0")
    from gi.repository import Gdk, Gtk

    box = spoke.builder.get_object("progressBox")
    status = spoke.builder.get_object("box1")
    bar = spoke.builder.get_object("progressBar")
    if box is None or bar is None:
        return

    css = Gtk.CssProvider()
    css.load_from_data(CSS)
    Gtk.StyleContext.add_provider_for_screen(Gdk.Screen.get_default(), css,
                                             Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION)

    view = Gtk.TextView(editable=False, cursor_visible=False, wrap_mode=Gtk.WrapMode.WORD_CHAR)
    view.get_style_context().add_class("doubletake-terminal")
    buf = view.get_buffer()
    buf.create_tag("time", foreground="#7d8590")
    buf.create_tag("mark", foreground="#ff6a13", weight=700)
    buf.create_tag("done", foreground="#3ecf8e", weight=700)

    scroll = Gtk.ScrolledWindow()
    scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
    scroll.set_size_request(-1, 440)
    scroll.set_vexpand(True)
    scroll.get_style_context().add_class("doubletake-frame")
    scroll.add(view)

    box.pack_start(scroll, True, True, 0)
    box.reorder_child(scroll, 0)

    # The progress line, below the panel, as wide as it (Nick, for the release): drawn from the installer's own bar
    # (hidden below), redrawn whenever the installer moves that bar on.
    line = Gtk.DrawingArea()
    line.set_size_request(-1, LINE_HEIGHT)
    line.set_margin_top(10)

    def draw(widget, cr):
        try:
            _draw_line(cr, widget.get_allocated_width(), widget.get_allocated_height(),
                       1.0 if getattr(spoke, "_dt_done", False) else bar.get_fraction())
        except Exception:
            log.exception("DoubleTake progress line not drawn")
        return False

    line.connect("draw", draw)
    bar.connect("notify::fraction", lambda *a: line.queue_draw())
    box.pack_start(line, False, False, 0)
    box.reorder_child(line, 1)  # straight after the panel
    line.show()
    spoke._dt_line = line
    box.set_valign(Gtk.Align.FILL)
    box.set_margin_top(24)
    box.set_margin_bottom(12)
    scroll.show_all()

    # The panel is in: now the bar and its label can go (and stay gone when the window
    # is shown again).
    for widget in (bar, status):
        if widget is not None:
            widget.set_no_show_all(True)
            widget.hide()

    spoke._dt_view = view
    spoke._dt_buffer = buf
    spoke._dt_last = ""
    _write(spoke, "DoubleTake installer", tag="mark")
    _write(spoke, "Preparing to install")


def _write(spoke, text, tag=None):
    buf = getattr(spoke, "_dt_buffer", None)
    if buf is None or not text or text == getattr(spoke, "_dt_last", None):
        return
    spoke._dt_last = text
    end = buf.get_end_iter()
    buf.insert_with_tags_by_name(end, time.strftime("%H:%M:%S") + "  ", "time")
    end = buf.get_end_iter()
    if tag:
        buf.insert_with_tags_by_name(end, text + "\n", tag)
    else:
        buf.insert(end, text + "\n")
    extra = buf.get_line_count() - MAX_LINES
    if extra > 0:
        buf.delete(buf.get_start_iter(), buf.get_iter_at_line(extra))
    mark = buf.get_mark("doubletake-end") or buf.create_mark("doubletake-end", buf.get_end_iter(), False)
    buf.move_mark(mark, buf.get_end_iter())
    spoke._dt_view.scroll_to_mark(mark, 0.0, False, 0.0, 1.0)


def _attach():
    from pyanaconda.ui.gui.spokes import installation_progress as progress
    from pyanaconda.ui.gui.utils import gtk_call_once

    spoke_class = progress.ProgressSpoke
    if getattr(spoke_class, "_doubletake", False):
        return
    plain_init = spoke_class.__init__
    plain_message = spoke_class._update_progress_message
    plain_done = spoke_class._installation_done

    def __init__(self, *args, **kwargs):
        plain_init(self, *args, **kwargs)
        try:
            _add_panel(self)
        except Exception:  # never stop the install over the look of it
            log.exception("DoubleTake progress panel not added; the progress bar stays")

    def _update_progress_message(self, message):
        plain_message(self, message)
        try:
            gtk_call_once(_write, self, str(message))
        except Exception:
            log.exception("DoubleTake progress panel: a step not shown")

    def _installation_done(self):
        try:
            self._dt_done = True
            if getattr(self, "_dt_line", None) is not None:
                self._dt_line.queue_draw()
            _write(self, "DoubleTake is installed. The tablet restarts by itself.", tag="done")
        except Exception:
            log.exception("DoubleTake progress panel: the last line not shown")
        plain_done(self)

    spoke_class.__init__ = __init__
    spoke_class._update_progress_message = _update_progress_message
    spoke_class._installation_done = _installation_done
    spoke_class._doubletake = True


try:
    _attach()
except Exception:  # a different installer: leave it exactly as it is
    log.exception("DoubleTake progress panel does not fit this installer; left as it is")
